func (s *EntireSettings) GetFullTranscriptGenerationRetentionDays() int {
	if s.StrategyOptions == nil {
		return defaultGenerationRetentionDays
	}

	val, ok := s.StrategyOptions["full_transcript_generation_retention_days"]
	if !ok {
